public int poisonousPlants(int[] p) {
    List<Integer> cur = new ArrayList<>();
    for (int x : p) cur.add(x);
    int days = 0;
    while (true) {
        List<Integer> next = new ArrayList<>();
        boolean died = false;
        next.add(cur.get(0));                 // first plant never dies
        for (int i = 1; i < cur.size(); i++) {
            if (cur.get(i) > cur.get(i - 1)) {
                died = true;                   // dies (using morning values)
            } else {
                next.add(cur.get(i));
            }
        }
        if (!died) break;
        days++;
        cur = next;
    }
    return days;
}

