def poisonousPlants(self, p: list[int]) -> int:
    cur = list(p)
    days = 0
    while True:
        nxt = [cur[0]]            # first plant never dies
        died = False
        for i in range(1, len(cur)):
            if cur[i] > cur[i - 1]:
                died = True       # dies (compare against morning values)
            else:
                nxt.append(cur[i])
        if not died:
            break
        days += 1
        cur = nxt
    return days

