public int poisonousPlants(int[] p) {
    int n = p.length;
    int[] day = new int[n];
    Deque<Integer> stack = new ArrayDeque<>();   // indices, non-increasing pesticide
    int answer = 0;
    for (int i = 0; i < n; i++) {
        int d = 0;
        while (!stack.isEmpty() && p[stack.peek()] >= p[i]) {
            d = Math.max(d, day[stack.peek()]);
            stack.pop();
        }
        day[i] = stack.isEmpty() ? 0 : d + 1;
        answer = Math.max(answer, day[i]);
        stack.push(i);
    }
    return answer;
}

